public class MainActivity extends FragmentActivity {
    private static final int NAVY=Color.rgb(22,58,105), BLUE=Color.rgb(38,133,214), BG=Color.rgb(247,249,252), TEXT=Color.rgb(28,39,54), MUTED=Color.rgb(103,115,132), LINE=Color.rgb(225,230,237);
    private static final int CAMERA_REQ=7101, IMAGE_REQ=7102, PDF_REQ=7103;
    private SharedPreferences prefs; private String currentUser; private LinearLayout content; private File scanFile; private Uri scanUri;
    private final Executor biometricExecutor=Executors.newSingleThreadExecutor();
    private final ArrayList<Uri> sessionUris=new ArrayList<>(); private final ArrayList<String> sessionTexts=new ArrayList<>();
    private boolean dniMode=false; private int dniSide=0;
    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private TextView tv(String s,float z,int c,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(b?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);v.setPadding(dp(6),dp(6),dp(6),dp(6));return v;}
    private EditText edit(String h){EditText e=new EditText(this);e.setHint(h);e.setSingleLine(true);e.setTextSize(16);e.setPadding(dp(14),0,dp(14),0);return e;}
    private EditText pin(String h){EditText e=edit(h);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);return e;}
    private GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));g.setStroke(dp(1),LINE);return g;}
    private Button action(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setTextSize(15);b.setAllCaps(false);b.setGravity(Gravity.CENTER);b.setTextColor(primary?Color.WHITE:TEXT);b.setBackground(bg(primary?BLUE:Color.WHITE,18));return b;}
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(NAVY);prefs=getSharedPreferences("rgapro_local",MODE_PRIVATE);if(!prefs.contains("user"))createUser();else showLogin();}
    private void createUser(){LinearLayout l=col();l.setBackgroundColor(BG);l.setPadding(dp(24),dp(20),dp(24),dp(24));l.setGravity(Gravity.CENTER_HORIZONTAL);l.addView(tv("RgaPro",32,NAVY,true));l.addView(tv("Bienvenido · acceso seguro",22,TEXT,true));EditText u=edit("Usuario"),p=pin("Clave de 6 dígitos"),p2=pin("Repite la clave");l.addView(u,new LinearLayout.LayoutParams(-1,dp(52)));l.addView(p,new LinearLayout.LayoutParams(-1,dp(52)));l.addView(p2,new LinearLayout.LayoutParams(-1,dp(52)));Button go=action("Crear acceso",true);l.addView(go,new LinearLayout.LayoutParams(-1,dp(56)));go.setOnClickListener(v->{if(u.getText().toString().trim().isEmpty()||!p.getText().toString().matches("\\d{6}")||!p.getText().toString().equals(p2.getText().toString())){Toast.makeText(this,"Usa una clave de 6 dígitos y repítela",Toast.LENGTH_LONG).show();return;}prefs.edit().putString("user",u.getText().toString().trim()).putString("pin",p.getText().toString()).putBoolean("biometric",true).apply();currentUser=u.getText().toString().trim();home();});l.addView(tv("🔒 Los datos se mantienen en el dispositivo.",13,MUTED,false));setContentView(l);}
    private void showLogin(){LinearLayout l=col();l.setBackgroundColor(BG);l.setPadding(dp(24),dp(20),dp(24),dp(24));l.setGravity(Gravity.CENTER_HORIZONTAL);l.addView(tv("RgaPro",32,NAVY,true));l.addView(tv("Acceso a tu cartera",22,TEXT,true));l.addView(tv("Clave + biometría",15,MUTED,false));Button key=action("🔐 Entrar con clave",true),bio=action("● Entrar con huella / biometría",false);l.addView(key,new LinearLayout.LayoutParams(-1,dp(56)));l.addView(bio,new LinearLayout.LayoutParams(-1,dp(56)));key.setOnClickListener(v->login());bio.setOnClickListener(v->biometricLogin());setContentView(l);}
    private void login(){EditText e=pin("Clave de 6 dígitos");AlertDialog d=new AlertDialog.Builder(this).setTitle("Entrar").setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Entrar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(prefs.getString("pin","").equals(e.getText().toString())){d.dismiss();currentUser=prefs.getString("user","");home();}else e.setError("Clave incorrecta");}));d.show();}
    private void biometricLogin(){if(!prefs.getBoolean("biometric",true)){Toast.makeText(this,"Biometría desactivada",Toast.LENGTH_SHORT).show();return;}int r=BiometricManager.from(this).canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_WEAK);if(r!=BiometricManager.BIOMETRIC_SUCCESS){Toast.makeText(this,"Biometría no disponible. Usa la clave.",Toast.LENGTH_LONG).show();return;}BiometricPrompt p=new BiometricPrompt(this,biometricExecutor,new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){runOnUiThread(()->{currentUser=prefs.getString("user","");home();});}});p.authenticate(new BiometricPrompt.PromptInfo.Builder().setTitle("RgaPro").setSubtitle("Acceso seguro").setNegativeButtonText("Usar clave").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_WEAK).build());}
    private void home(){LinearLayout root=col();root.setBackgroundColor(BG);LinearLayout top=col();top.setBackgroundColor(NAVY);top.setGravity(Gravity.CENTER);top.addView(tv("RgaPro",28,Color.WHITE,true));top.addView(tv("Bienvenido, "+currentUser+" 👋",17,Color.WHITE,false));root.addView(top,new LinearLayout.LayoutParams(-1,dp(110)));ScrollView sc=new ScrollView(this);LinearLayout body=col();body.setPadding(dp(18),dp(18),dp(18),dp(20));body.addView(tv("¿Qué quieres hacer hoy?",22,TEXT,true));menu(body,"👤","Clientes","Buscar por nombre, DNI, teléfono, email o póliza",v->clients());menu(body,"▣","Pólizas","Auto · hogar · vida · salud · decesos · otros",v->policies());menu(body,"▤","Documentos","DNI doble cara · varias páginas · JPEG · PDF · OCR",v->scanDocument());menu(body,"🔔","Vencimientos","60 · 45 · 30 · 15 días",v->expiries());menu(body,"🔒","Seguridad","Clave, biometría y compartir solo cuando tú quieras",v->security());sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Button out=action("Cerrar sesión",false);root.addView(out,new LinearLayout.LayoutParams(-1,dp(52)));out.setOnClickListener(v->showLogin());setContentView(root);}
    private void menu(LinearLayout b,String icon,String title,String sub,View.OnClickListener c){LinearLayout x=new LinearLayout(this);x.setGravity(Gravity.CENTER_VERTICAL);x.setPadding(dp(12),dp(8),dp(12),dp(8));x.setBackground(bg(Color.WHITE,18));TextView i=tv(icon,28,BLUE,true);x.addView(i,new LinearLayout.LayoutParams(dp(48),dp(68)));LinearLayout w=col();w.addView(tv(title,18,TEXT,true));w.addView(tv(sub,13,MUTED,false));x.addView(w,new LinearLayout.LayoutParams(0,dp(68),1));x.addView(tv("›",30,MUTED,false),new LinearLayout.LayoutParams(dp(28),dp(68)));x.setOnClickListener(c);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(86));p.bottomMargin=dp(10);b.addView(x,p);}
    private void page(String title,String sub){LinearLayout r=col();r.setBackgroundColor(BG);LinearLayout h=col();h.setBackgroundColor(NAVY);h.setPadding(dp(16),dp(10),dp(16),dp(10));Button back=action("‹",false);back.setTextColor(Color.WHITE);back.setBackgroundColor(Color.TRANSPARENT);back.setOnClickListener(v->home());h.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));h.addView(tv(title,20,Color.WHITE,true));h.addView(tv(sub,12,Color.WHITE,false));r.addView(h);content=col();content.setPadding(dp(16),dp(16),dp(16),dp(20));ScrollView s=new ScrollView(this);s.addView(content);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
    private JSONArray data(){try{return new JSONArray(prefs.getString("policies","[]"));}catch(Exception e){return new JSONArray();}}
    private void save(JSONArray a){prefs.edit().putString("policies",a.toString()).apply();}
    private void clients(){page("Clientes","Busca por cualquier dato");EditText q=edit("Nombre, DNI, teléfono, email, póliza…");content.addView(q,new LinearLayout.LayoutParams(-1,dp(54)));LinearLayout list=col();content.addView(list);Runnable r=()->{list.removeAllViews();JSONArray a=data();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&match(p,q.getText().toString())){Button x=action("👤 "+p.optString("holder","Sin titular")+"\n"+p.optString("type","Otros")+" · "+p.optString("number",""),false);x.setOnClickListener(v->detail(p));list.addView(x,new LinearLayout.LayoutParams(-1,dp(72)));}}};q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){r.run();}public void afterTextChanged(android.text.Editable e){}});r.run();}
    private boolean match(JSONObject p,String q){if(q==null||q.trim().isEmpty())return true;String n=q.toLowerCase(Locale.ROOT);for(String k:new String[]{"holder","holderDni","phone","email","address","type","number","expiry","ocrText","members"})if(p.optString(k).toLowerCase(Locale.ROOT).contains(n))return true;return false;}
    private void detail(JSONObject p){new AlertDialog.Builder(this).setTitle("Ficha de cliente").setMessage("Titular: "+p.optString("holder","—")+"\nDNI/NIE: "+p.optString("holderDni","—")+"\nTeléfono: "+p.optString("phone","—")+"\nEmail: "+p.optString("email","—")+"\nTipo: "+p.optString("type","—")+"\nPóliza: "+p.optString("number","—")+"\nVencimiento: "+p.optString("expiry","—")).setPositiveButton("Cerrar",null).show();}
    private void policies(){page("Pólizas","Separadas por tipo");Spinner sp=new Spinner(this);String[] types={"Todas","Auto","Hogar","Vida","Salud","Decesos","Otros"};sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,types));content.addView(sp,new LinearLayout.LayoutParams(-1,dp(52)));LinearLayout list=col();content.addView(list);Runnable r=()->{list.removeAllViews();String f=String.valueOf(sp.getSelectedItem());JSONArray a=data();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&(f.equals("Todas")||f.equalsIgnoreCase(p.optString("type","Otros")))){Button x=action(p.optString("type","Otros")+" · "+p.optString("holder","Sin titular")+"\n"+p.optString("number","—")+" · "+p.optString("expiry","—"),false);x.setOnClickListener(v->detail(p));list.addView(x,new LinearLayout.LayoutParams(-1,dp(72)));}}};sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> a,View v,int p,long id){r.run();}public void onNothingSelected(android.widget.AdapterView<?> a){}});r.run();}
    private void expiries(){page("Próximos vencimientos","60 · 45 · 30 · 15 días");JSONArray a=data();SimpleDateFormat f=new SimpleDateFormat("dd/MM/yyyy",Locale.ROOT);Date now=new Date();boolean any=false;for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);try{long d=(f.parse(p.optString("expiry")).getTime()-now.getTime())/(86400000L);if(d>=0&&d<=60){any=true;content.addView(tv(p.optString("holder","Sin titular")+" · "+p.optString("type","Otros")+" · "+d+" días",17,TEXT,true),new LinearLayout.LayoutParams(-1,dp(64)));}}catch(Exception ignored){}}if(!any)content.addView(tv("No hay pólizas en los próximos 60 días.",16,MUTED,false));}
    private void security(){page("Seguridad","Tú decides");Switch b=new Switch(this);b.setText("Permitir acceso biométrico");b.setChecked(prefs.getBoolean("biometric",true));content.addView(b,new LinearLayout.LayoutParams(-1,dp(58)));b.setOnCheckedChangeListener((x,v)->prefs.edit().putBoolean("biometric",v).apply());Button test=action("Probar biometría",false);content.addView(test,new LinearLayout.LayoutParams(-1,dp(54)));test.setOnClickListener(v->biometricLogin());Button sh=action("Compartir datos almacenados…",false);content.addView(sh,new LinearLayout.LayoutParams(-1,dp(54)));sh.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,"RgaPro: compartición iniciada por el usuario.");startActivity(Intent.createChooser(i,"Compartir"));});content.addView(tv("No se comparte nada automáticamente.",13,MUTED,false));}
    private void scanDocument(){page("Escanear documento","DNI doble cara · multipágina · JPEG · PDF");content.addView(tv("Para DNI: primero cara frontal y después reverso. Para contratos y otros documentos puedes añadir tantas páginas como necesites.",15,MUTED,false));Button dni=action("🪪 DNI · 2 caras",true);content.addView(dni,new LinearLayout.LayoutParams(-1,dp(56)));dni.setOnClickListener(v->{dniMode=true;dniSide=0;sessionUris.clear();sessionTexts.clear();openCamera();});Button multi=action("📷 Documento de varias páginas",false);content.addView(multi,new LinearLayout.LayoutParams(-1,dp(56)));multi.setOnClickListener(v->{dniMode=false;sessionUris.clear();sessionTexts.clear();openCamera();});Button jpg=action("🖼 JPEG/JPG · una o varias fotos",false);content.addView(jpg,new LinearLayout.LayoutParams(-1,dp(56)));jpg.setOnClickListener(v->pickImages());Button pdf=action("📄 PDF · todas las páginas",false);content.addView(pdf,new LinearLayout.LayoutParams(-1,dp(56)));pdf.setOnClickListener(v->pickPdf());}
    private void openCamera(){if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA},CAMERA_REQ);return;}try{File d=new File(getCacheDir(),"scans");if(!d.exists())d.mkdirs();scanFile=File.createTempFile("rgapro_",".jpg",d);scanUri=FileProvider.getUriForFile(this,getPackageName()+".fileprovider",scanFile);Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);i.putExtra(MediaStore.EXTRA_OUTPUT,scanUri);i.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(i,CAMERA_REQ);}catch(Exception e){Toast.makeText(this,"No se pudo abrir la cámara",Toast.LENGTH_LONG).show();}}
    private void pickImages(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/jpeg");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMAGE_REQ);}
    private void pickPdf(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/pdf");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PDF_REQ);}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==CAMERA_REQ&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)openCamera();}
    @Override protected void onActivityResult(int r,int result,Intent dataIntent){super.onActivityResult(r,result,dataIntent);if(result!=RESULT_OK)return;if(r==CAMERA_REQ){sessionUris.add(scanUri);runOcrSequential();}else if(r==IMAGE_REQ){if(dataIntent!=null&&dataIntent.getClipData()!=null){ClipData c=dataIntent.getClipData();for(int i=0;i<c.getItemCount();i++)sessionUris.add(c.getItemAt(i).getUri());}else if(dataIntent!=null&&dataIntent.getData()!=null)sessionUris.add(dataIntent.getData());runOcrSequential();}else if(r==PDF_REQ&&dataIntent!=null&&dataIntent.getData()!=null){processPdf(dataIntent.getData());}}
    private void runOcrSequential(){if(sessionUris.isEmpty()){showOcrResult();return;}sessionTexts.clear();runOcrAt(0);}
    private void runOcrAt(int index){if(index>=sessionUris.size()){showOcrResult();return;}try{TextRecognizer z=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);z.process(InputImage.fromFilePath(this,sessionUris.get(index))).addOnSuccessListener(t->{sessionTexts.add(t.getText());z.close();runOcrAt(index+1);}).addOnFailureListener(e->{sessionTexts.add("");z.close();runOcrAt(index+1);});}catch(Exception e){sessionTexts.add("");runOcrAt(index+1);}}
    private void processPdf(Uri uri){setContentView(tv("Leyendo PDF página por página…",18,TEXT,true));new Thread(()->{ArrayList<Bitmap> pages=new ArrayList<>();try(ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(uri,"r")){if(fd==null)throw new Exception();PdfRenderer r=new PdfRenderer(fd);for(int i=0;i<r.getPageCount();i++){PdfRenderer.Page p=r.openPage(i);Bitmap b=Bitmap.createBitmap(p.getWidth()*2,p.getHeight()*2,Bitmap.Config.ARGB_8888);p.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);p.close();pages.add(b);}r.close();}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"No se pudo leer el PDF",Toast.LENGTH_LONG).show());return;}runOnUiThread(()->ocrBitmaps(pages,0,new StringBuilder()));}).start();}
    private void ocrBitmaps(ArrayList<Bitmap> pages,int i,StringBuilder all){if(i>=pages.size()){sessionTexts.clear();sessionTexts.add(all.toString());showOcrResult();return;}TextRecognizer z=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);z.process(InputImage.fromBitmap(pages.get(i),0)).addOnSuccessListener(t->all.append(t.getText()).append("\n\n")).addOnCompleteListener(x->{z.close();ocrBitmaps(pages,i+1,all);});}
    private void showOcrResult(){StringBuilder raw=new StringBuilder();for(String s:sessionTexts)raw.append(s).append("\n\n");String text=raw.toString();String dni=extract(text,"\\b(?:[XYZ]?[0-9]{7}[A-Z]|[0-9]{8}[A-Z])\\b",0);String phone=extract(text,"(?:\\+34\\s?)?[6789][0-9]{8}",0);String email=extract(text,"[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}",Pattern.CASE_INSENSITIVE);String date=extract(text,"\\b(?:0?[1-9]|[12][0-9]|3[01])[/.-](?:0?[1-9]|1[0-2])[/.-](?:19|20)\\d{2}\\b",0);String name=guessName(text);LinearLayout box=col();EditText n=edit("Nombre / titular");n.setText(name);EditText d=edit("DNI / NIE");d.setText(dni);EditText ph=edit("Teléfono");ph.setText(phone);EditText em=edit("Email");em.setText(email);EditText ex=edit("Vencimiento");ex.setText(date.replace('.','/').replace('-','/'));Spinner type=new Spinner(this);String[] types={"Auto","Hogar","Vida","Salud","Decesos","Otros"};type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,types));box.addView(n);box.addView(d);box.addView(ph);box.addView(em);box.addView(ex);box.addView(type);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(dniMode?(dniSide==0?"DNI · cara frontal leída":"DNI · ambas caras leídas"):"Datos detectados por OCR").setMessage("Se han procesado "+sessionTexts.size()+" imagen(es/página(s)). Revisa los campos antes de guardar.").setView(box).setNegativeButton("Descartar",null).setPositiveButton("Guardar cliente",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{saveClient(n.getText().toString(),d.getText().toString(),ph.getText().toString(),em.getText().toString(),ex.getText().toString(),String.valueOf(type.getSelectedItem()),text);dialog.dismiss();}));dialog.show();if(dniMode&&dniSide==0){Button b=action("📷 Fotografiar REVERSO del DNI",true);b.setOnClickListener(v->{dniSide=1;openCamera();});content.addView(b,new LinearLayout.LayoutParams(-1,dp(56)));}else{Button b=action("➕ Añadir otra cara / página",false);b.setOnClickListener(v->openCamera());content.addView(b,new LinearLayout.LayoutParams(-1,dp(56)));}}
    private String extract(String t,String r,int f){Matcher m=Pattern.compile(r,f).matcher(t.replace("\n"," "));return m.find()?m.group():"";}
    private String guessName(String raw){for(String line:raw.split("\\r?\\n")){String s=line.trim();if(s.toUpperCase(Locale.ROOT).contains("NOMBRE")){s=s.replaceFirst("(?i).*?NOMBRE[:\\s-]*","").trim();if(s.length()>2)return s;}}return "";}
    private void saveClient(String n,String d,String ph,String em,String ex,String type,String raw){try{JSONArray a=data();JSONObject p=new JSONObject();p.put("holder",n.trim());p.put("holderDni",d.trim().toUpperCase(Locale.ROOT));p.put("phone",ph.trim());p.put("email",em.trim());p.put("expiry",ex.trim());p.put("type",type);p.put("number","");p.put("ocrText",raw);p.put("members",new JSONArray());a.put(p);save(a);Toast.makeText(this,"Cliente guardado en Clientes",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"No se pudo guardar",Toast.LENGTH_LONG).show();}}
}
